// Some portions generated by Claude

// Plan milestone M8: in-page navigation between router-ready routes.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-router');
const PAGE_MODEL = 'application/vnd.rdf4j.workbench+ndjson';

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm', 'spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Every document the main frame requests from now on. */
function recordDocumentRequests(page) {
	const requests = [];
	page.on('request', (request) => {
		if (request.resourceType() === 'document' && request.frame() === page.mainFrame()) {
			requests.push(request.url());
		}
	});
	return requests;
}

async function openRoute(page, view) {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, view));
	await expectRoute(page, view);
}

async function expectRoute(page, view) {
	await expect(page).toHaveURL(new RegExp(`/repositories/${REPOSITORY_ID}/${view}$`));
	const outlet = page.locator('#workbench-outlet');
	await expect(outlet).toHaveAttribute('data-workbench-route', view);
	await expect(outlet).toHaveAttribute('data-workbench-route-ready', 'true');
}

function menuLink(page, name) {
	return page.locator('#navigation').getByRole('link', { name, exact: true });
}

test('menu links change the page without loading a document, and Back returns', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await openRoute(page, 'summary');
	const documents = recordDocumentRequests(page);
	await page.evaluate(() => {
		window.__shellMarker = document.querySelector('#workbench-contextbar');
	});

	for (const [name, view, heading] of [['Namespaces', 'namespaces', 'Namespaces In Repository'],
		['Types', 'types', 'Types In Repository'], ['Graphs', 'contexts', 'Graphs']]) {
		await menuLink(page, name).click();
		await expectRoute(page, view);
		await expect(page.locator('#workbench-outlet h1')).toHaveText(heading);
	}

	expect(documents).toEqual([]);
	expect(await page.evaluate(() => window.__shellMarker === document.querySelector('#workbench-contextbar')))
		.toBe(true);
	await page.goBack();
	await expectRoute(page, 'types');
	await expect(page.locator('#workbench-outlet h1')).toHaveText('Types In Repository');
	expect(documents).toEqual([]);
	await expect(page).toHaveTitle(`Types · ${REPOSITORY_ID} — RDF4J Workbench`);
});

test('a slow page keeps the old one visible, and a newer click wins', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await openRoute(page, 'namespaces');
	const documents = recordDocumentRequests(page);
	await page.route((url) => url.pathname.endsWith(`/repositories/${REPOSITORY_ID}/types`), async (route) => {
		if ((route.request().headers().accept || '').includes(PAGE_MODEL)) {
			await new Promise((resolve) => setTimeout(resolve, 1500));
		}
		// The router may have abandoned the request by now.
		await route.continue().catch(() => {});
	});

	await menuLink(page, 'Types').click();
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('aria-busy', 'true');
	await expect(page.locator('#workbench-outlet h1')).toHaveText('Namespaces In Repository');
	await expect(page).toHaveURL(new RegExp('/namespaces$'));
	await menuLink(page, 'Graphs').click();

	await expectRoute(page, 'contexts');
	await page.waitForTimeout(1700);
	await expectRoute(page, 'contexts');
	await expect(page.locator('#workbench-outlet h1')).toHaveText('Graphs');
	await expect(page.locator('#workbench-outlet')).not.toHaveAttribute('aria-busy', 'true');
	expect(documents).toEqual([]);
});

test('?router=off starts the Workbench without in-page navigation', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary') + '?router=off');
	await expect(page.locator('#workbench-outlet h1')).toBeVisible();
	const documents = recordDocumentRequests(page);

	await menuLink(page, 'Types').click();

	await expect(page).toHaveURL(new RegExp('/types$'));
	await expect(page.locator('#workbench-outlet h1')).toHaveText('Types In Repository');
	expect(documents.length).toBe(1);
});

// Plan task M8.2: scroll, focus and announcements.

test('Back returns to the scroll position the page was left at', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await openRoute(page, 'types');
	await page.evaluate(() => window.scrollTo(0, 1200));
	await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(1150);

	await menuLink(page, 'Summary').click();
	await expectRoute(page, 'summary');
	expect(await page.evaluate(() => window.scrollY)).toBe(0);
	await page.goBack();
	await expectRoute(page, 'types');

	await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(1150);
	expect(Math.abs(await page.evaluate(() => window.scrollY) - 1200)).toBeLessThanOrEqual(50);
});

test('after a menu click the new heading has focus and the page is announced', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await openRoute(page, 'summary');

	await menuLink(page, 'Namespaces').click();
	await expectRoute(page, 'namespaces');

	await expect(page.locator('#workbench-outlet h1')).toBeFocused();
	await expect(page.locator('#workbench-route-status')).toHaveText('Namespaces loaded');
	await expect(page.locator('#workbench-route-status')).toHaveAttribute('aria-live', 'polite');
});

// Plan task M8.3: after an in-page navigation the shell is what a page load of the same URL shows.

/** The menu and the context bar as a reader sees them (Lit's comment markers removed). */
async function shellSnapshot(page) {
	return page.evaluate(() => ({
		navigation: document.querySelector('#navigation').outerHTML.replace(/<!--[\s\S]*?-->/g, ''),
		contextBar: document.querySelector('#workbench-contextbar').innerText,
		title: document.title
	}));
}

async function expectSameShellAfterReload(page, view) {
	const navigated = await shellSnapshot(page);
	await page.reload();
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route', view);
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route-ready', 'true');
	expect(navigated).toEqual(await shellSnapshot(page));
}

test('choosing a repository from the list shows the shell a page load would show', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl('NONE', 'repositories'));
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route-ready', 'true');
	const documents = recordDocumentRequests(page);

	await page.locator('#repositories-results a.workbench-repository-link', { hasText: REPOSITORY_ID }).first().click();
	await expectRoute(page, 'summary');
	expect(documents).toEqual([]);
	await expect(page.locator('#workbench-repository-switcher')).toContainText(REPOSITORY_ID);

	await expectSameShellAfterReload(page, 'summary');
});

test('leaving a repository for the repository list shows the shell a page load would show', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await openRoute(page, 'summary');
	const documents = recordDocumentRequests(page);

	await menuLink(page, 'Repositories').click();
	await expect(page).toHaveURL(/\/repositories\/NONE\/repositories$/);
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route', 'repositories');
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route-ready', 'true');
	expect(documents).toEqual([]);

	await expectSameShellAfterReload(page, 'repositories');
});

test('leaving Query for Namespaces shows the shell a page load would show', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route-ready', 'true');

	await menuLink(page, 'Namespaces').click();
	await expectRoute(page, 'namespaces');

	await expectSameShellAfterReload(page, 'namespaces');
});

test('the repository switcher lists the repositories for the page that is shown', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl('NONE', 'repositories'));
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route-ready', 'true');
	const option = page.locator(`#workbench-repository-options a[data-repository-id="${REPOSITORY_ID}"]`);
	await page.locator('#workbench-repository-switcher').click();
	await expect(option).toBeVisible();
	await page.keyboard.press('Escape');

	await page.locator('#repositories-results a.workbench-repository-link', { hasText: REPOSITORY_ID }).first().click();
	await expectRoute(page, 'summary');
	await menuLink(page, 'Types').click();
	await expectRoute(page, 'types');
	await page.locator('#workbench-repository-switcher').click();

	await expect(option).toBeVisible();
	await expect(option).toHaveAttribute('aria-current', 'true');
	await expect(option).toHaveAttribute('href', new RegExp(`/repositories/${REPOSITORY_ID}/types$`));
});
